from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r,c)])
            seen[r][c] = True
            cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and not seen[yy][xx] and grid[yy][xx]==color:
                        seen[yy][xx]=True; q.append((yy,xx))
            rs=[y for y,x in cells]; cs=[x for y,x in cells]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            area=(r1-r0+1)*(c1-c0+1)
            # Coherent multi-cell blobs are objects; sparse/isolated marks are noise.
            if len(cells)>=4 and len(cells)*2>=area:
                comps.append((color,cells,r0,r1,c0,c1))
    out=[[bg]*w for _ in range(h)]
    for color,cells,*_ in comps:
        for r,c in cells:
            out[r][c]=color
    # These objects are rectangular panels: overwrite intruding noise cells as well.
    for color,cells,r0,r1,c0,c1 in comps:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c]=color
    return out
